          idCache[file.name] = id;
        }

        let libraryItem = {
          id: id,
          fileName: file.name,
          width: width,
          height: height,
          creationDate: file.lastModifiedDate.toISOString(), // file contains only lastModifiedDate
          //TODO: latitude, using exif-js
